CREATE TABLE IF NOT EXISTS `#__intercom_connections` (`provider` varchar(64) NOT NULL, `envelope` mediumtext NOT NULL, PRIMARY KEY (`provider`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO `#__intercom_connections` (`provider`,`envelope`) VALUES ('cleverreach','');
CREATE TABLE IF NOT EXISTS `#__intercom_drafts` (`id` int unsigned NOT NULL AUTO_INCREMENT, `owner_id` int unsigned NOT NULL, `delivery_mode` varchar(8) NOT NULL DEFAULT 'live', `content` mediumtext NOT NULL, `revision` int unsigned NOT NULL DEFAULT 1, `tested_revision` int unsigned DEFAULT NULL, `state` varchar(24) NOT NULL DEFAULT 'draft', `filter_id` int unsigned DEFAULT NULL, `mailing_id` int unsigned NOT NULL DEFAULT 0, `send_at` bigint unsigned NOT NULL DEFAULT 0, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, PRIMARY KEY (`id`), KEY `owner` (`owner_id`), KEY `state_time` (`state`,`updated_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `#__intercom_filters` (`filter_id` int unsigned NOT NULL, `draft_id` int unsigned DEFAULT NULL, PRIMARY KEY (`filter_id`), UNIQUE KEY `draft` (`draft_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `#__intercom_revisions` (`id` int unsigned NOT NULL AUTO_INCREMENT, `draft_id` int unsigned NOT NULL, `revision` int unsigned NOT NULL, `content` mediumtext NOT NULL, `created_at` datetime NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `revision` (`draft_id`,`revision`), KEY `created` (`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `#__intercom_audit` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `actor_id` int unsigned NOT NULL, `event` varchar(80) NOT NULL, `draft_id` int unsigned NOT NULL DEFAULT 0, `context` mediumtext NOT NULL, `created_at` datetime NOT NULL, PRIMARY KEY (`id`), KEY `created` (`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
